// Lote 1b, tool 1: the logic of the top-down map ("Mapa y vista cenital"), a line-by-line port of src/shared/minimap.ts. Pure C# (no UnityEngine), so the
// EditMode golden test (contracts/golden/minimap.json, generated by the web's own code) runs it directly.
//
// Frames. World coordinates are the local NED of TelemetryFrame.p: north `n` and east `e`, metres, relative to the EKF origin (in the simulator, the
// take-off point). Yaw is clockwise from north, radians (PX4 / aerospace). Screen coordinates are pixels with y down and are returned RELATIVE TO THE
// CENTRE of the view (0, 0 = the middle of the map): the caller adds the half size of its drawing area.
//
// The map has no base layer and no latitude / longitude: the wire carries neither.

using System;
using System.Collections.Generic;
using System.Globalization;

namespace WebGL.Telemetry
{
    /// <summary>What the map shows: metres per pixel and the world point at the centre.</summary>
    public struct MapView
    {
        public double scale, centerN, centerE;
        public MapView(double scale, double centerN, double centerE) { this.scale = scale; this.centerN = centerN; this.centerE = centerE; }
    }

    /// <summary>A circular geofence around (n, e) (default the origin) with `radius` m. Simulator only; nothing for the replay and PX4 SITL.</summary>
    public sealed class MapFence
    {
        public double radius, n, e;
        public MapFence(double radius, double n = 0, double e = 0) { this.radius = radius; this.n = n; this.e = e; }
    }

    /// <summary>
    /// The path flown so far: (north, east) pairs, oldest first. `Seg` is the segment of the last point (a change of segment = a discontinuity: the replay
    /// loop wrapped). The web keeps it immutable; here the same rules mutate one object (Push says whether anything changed, so a caller can skip a redraw).
    /// </summary>
    public sealed class MapTrail
    {
        readonly List<double> pts = new List<double>(256); // n0, e0, n1, e1, ...

        public int? Seg { get; private set; }
        public int Count => pts.Count / 2;
        public double N(int i) => pts[2 * i];
        public double E(int i) => pts[2 * i + 1];

        /// <summary>A new, empty trail: on a new `hello` (a new session) and when the source changes.</summary>
        public void Clear() { pts.Clear(); Seg = null; }

        /// <summary>
        /// Adds the position `p` (NED: p[0] north, p[1] east; extra components are ignored) when it moved at least `minStep` metres from the last point.
        /// A frame of another `seg` empties the trail first and starts a new one with that point. The oldest points above `max` are dropped.
        /// </summary>
        public bool Push(double[] p, int seg, double minStep = Minimap.TrailMinStep, int max = Minimap.TrailMax)
        {
            double n = p[0], e = p[1];
            if (Seg.HasValue && Seg.Value != seg)
            {
                pts.Clear();
                pts.Add(n); pts.Add(e);
                Seg = seg;
                return true;
            }
            int c = Count;
            if (c > 0 && Minimap.Hypot(n - pts[2 * c - 2], e - pts[2 * c - 1]) < minStep) return false;
            if (c >= max) pts.RemoveRange(0, 2 * (c - max + 1));
            pts.Add(n); pts.Add(e);
            Seg = seg;
            return true;
        }
    }

    public static class Minimap
    {
        /// <summary>Smallest scale the map zooms to, m per px: no zoom above ~5 m of side.</summary>
        public const double MinScale = 0.05;
        /// <summary>The trail keeps at most this many points; the oldest are dropped.</summary>
        public const int TrailMax = 1200;
        /// <summary>A new trail point is only added once the vehicle moved this far from the last one, m.</summary>
        public const double TrailMinStep = 0.5;
        /// <summary>"Follow" never zooms in beyond this scale, m per px, so a moving drone does not leave the view at once.</summary>
        public const double FollowMinScale = 0.25;

        internal static double Hypot(double a, double b) => Math.Sqrt(a * a + b * b);

        /// <summary>Heading of the body from its attitude quaternion (Hamilton, scalar first, body FRD to world NED): yaw in rad, clockwise from north, (-pi, pi].</summary>
        public static double YawFromQuat(double[] q)
        {
            double w = q[0], x = q[1], y = q[2], z = q[3];
            return Math.Atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z));
        }

        /// <summary>
        /// The view that shows all the points (trail, origin, vehicle; `points` = n0, e0, n1, e1, ...) and the geofence inside a circular map of diameter
        /// `sizePx`, keeping `marginPx` of air at the edge. The centre is the middle of the bounding box; the scale (m/px) is the distance from that centre to
        /// the farthest thing divided by the radius that is left (`sizePx / 2 - marginPx`), never below MinScale. With nothing to show it is the origin at MinScale.
        /// </summary>
        public static MapView FitView(IReadOnlyList<double> points, MapFence fence, double sizePx, double marginPx = 12)
        {
            double minN = double.PositiveInfinity, maxN = double.NegativeInfinity, minE = double.PositiveInfinity, maxE = double.NegativeInfinity;
            int count = points != null ? points.Count / 2 : 0;
            for (int i = 0; i < count; i++)
            {
                double n = points[2 * i], e = points[2 * i + 1];
                if (n < minN) minN = n;
                if (n > maxN) maxN = n;
                if (e < minE) minE = e;
                if (e > maxE) maxE = e;
            }
            double fn = fence != null ? fence.n : 0, fe = fence != null ? fence.e : 0;
            if (fence != null)
            {
                minN = Math.Min(minN, fn - fence.radius);
                maxN = Math.Max(maxN, fn + fence.radius);
                minE = Math.Min(minE, fe - fence.radius);
                maxE = Math.Max(maxE, fe + fence.radius);
            }
            if (double.IsPositiveInfinity(minN)) return new MapView(MinScale, 0, 0);
            double centerN = (minN + maxN) / 2, centerE = (minE + maxE) / 2;
            double reach = 0;
            for (int i = 0; i < count; i++) reach = Math.Max(reach, Hypot(points[2 * i] - centerN, points[2 * i + 1] - centerE));
            if (fence != null) reach = Math.Max(reach, Hypot(fn - centerN, fe - centerE) + fence.radius);
            double avail = Math.Max(1, sizePx / 2 - marginPx);
            return new MapView(Math.Max(MinScale, reach / avail), centerN, centerE);
        }

        /// <summary>"Follow": the vehicle at the centre, at `fitScale` but not closer than FollowMinScale.</summary>
        public static MapView FollowView(double n, double e, double fitScale) => new MapView(Math.Max(fitScale, FollowMinScale), n, e);

        static readonly int[] Mantissas = { 5, 2, 1 };

        /// <summary>The scale bar: the longest 1-2-5 x 10^k metres that fits in `maxPx` pixels at `scale` m/px, and its length in px.</summary>
        public static void ScaleBar(double scale, double maxPx, out double metres, out double px)
        {
            metres = 0; px = 0;
            if (!(scale > 0) || !(maxPx > 0)) return;
            double limit = maxPx * scale * (1 + 1e-12);
            int k = (int)Math.Floor(Math.Log10(limit));
            for (int kk = k + 1; kk >= k - 1; kk--)
            {
                foreach (int m in Mantissas)
                {
                    double v = m * Math.Pow(10, kk);
                    if (v <= limit && v > metres) metres = v;
                }
            }
            px = metres / scale;
        }

        /// <summary>
        /// World point to screen, in px from the centre of the view, y down. North up (`headingUp` false): x = east, -y = north. Heading up: the map turns so
        /// that the vehicle's nose (`yaw`, rad clockwise from north) points to the top: x = to the right of the nose, -y = ahead of it.
        /// </summary>
        public static void ToScreen(double n, double e, MapView view, bool headingUp, double yaw, out double x, out double y)
        {
            double dn = n - view.centerN, de = e - view.centerE;
            if (!headingUp) { x = de / view.scale; y = -dn / view.scale; return; }
            double c = Math.Cos(yaw), s = Math.Sin(yaw);
            x = (-dn * s + de * c) / view.scale;
            y = -(dn * c + de * s) / view.scale;
        }

        /// <summary>
        /// Where the arrow of the vehicle and the "N" of north point on the screen, rad clockwise from the top. North up: the arrow turns with the vehicle and
        /// north stays up. Heading up: the arrow stays up and it is the map (north) that turns, the opposite way.
        /// </summary>
        public static void ViewAngles(bool headingUp, double yaw, out double arrow, out double north)
        {
            if (headingUp) { arrow = 0; north = -yaw; }
            else { arrow = yaw; north = 0; }
        }

        /// <summary>"20 m" or "2 km" for the scale bar.</summary>
        public static string ScaleLabel(double metres)
        {
            // a power of ten below 1 comes out of Math.Pow with noise in the last digits (0.5 = 5 * 10^-1): the label shows what JS prints for the exact value
            return metres >= 1000 ? Num(metres / 1000) + " km" : Num(metres) + " m";
        }

        static string Num(double x) => Math.Round(x, 9).ToString("R", CultureInfo.InvariantCulture);
    }
}
